// Folio document model — TypeScript mirror.
// In the app this file is GENERATED by ts-rs from crates/folio-model (see project.rs); keep the two in step.
// All lengths are points (1/72 in). Spread space: origin at top-left of the left page's trim; negative = bleed.

export type Pt = number;
export type Id<T extends string> = string & { readonly __kind: T };
export type BookId = Id<'book'>; export type SpreadId = Id<'spread'>; export type PageId = Id<'page'>;
export type FrameId = Id<'frame'>; export type FlowId = Id<'flow'>; export type StyleId = Id<'style'>;
export type MasterId = Id<'master'>; export type AssetPath = string; // package-relative, e.g. "assets/images/<sha>.jpg"

export type BookKind = 'picture' | 'novel' | 'textbook' | 'illustrated' | 'poetry' | 'memoir';
export type LayoutMode = 'fixed' | 'flowing';
export type Units = 'in' | 'mm';

export interface Size { w: Pt; h: Pt }
export interface Box { x: Pt; y: Pt; w: Pt; h: Pt }
export interface Margins { top: Pt; bottom: Pt; inside: Pt; outside: Pt }

export interface Book {
  schema: 1;
  id: BookId;
  title: string;
  subtitle?: string;
  authors: { name: string; role: 'author' | 'illustrator' | 'editor' | 'translator' }[];
  language: string;               // BCP 47, e.g. "en-CA"
  kind: BookKind;
  layout: LayoutMode;
  trim: Size;
  bleed: Pt;                      // 0 when the book has no bleed
  margins: Margins;
  adjustGutterForPageCount: boolean;
  grid: Grid;
  spreads: Spread[];
  flows: Flow[];
  masters: MasterId[];            // detail in masters.json
  metadata: BookMetadata;
  extensions?: Record<string, unknown>; // preserved verbatim (imports, future versions)
}

export interface Grid { columns: number; gutter: Pt; baseline: { increment: Pt; offset: Pt } | null }

export type SpreadKind = 'cover' | 'single' | 'spread' | 'opener' | 'closer';
export interface Spread {
  id: SpreadId;
  kind: SpreadKind;
  pages: Page[];                  // 1 or 2
  frames: Frame[];                // z-order = array order
  guides?: Guide[];
  masterOverrides?: { pageId: PageId; hide: FrameId[] }[];
}
export interface Page { id: PageId; master: MasterId | null; numberFormat?: 'arabic' | 'roman-lower' | 'none' }
export interface Guide { axis: 'x' | 'y'; pos: Pt; locked: boolean }

interface FrameBase { id: FrameId; box: Box; rotation?: number; locked?: boolean; name?: string; fromMaster?: MasterId; description?: string }
export interface TextFrame extends FrameBase {
  type: 'text';
  style: StyleId;
  content?: { inline: string | Run[] }; // short, self-contained text
  flow?: { id: FlowId; index: number }; // or a slot in a flow
  columns?: number; columnGap?: Pt; inset?: Pt;
  verticalAlign?: 'top' | 'middle' | 'bottom';
  baselineLock?: boolean;
  overrides?: Partial<ParagraphStyle>; // e.g. per-box size, align, bold/italic
}
export interface ImageFrame extends FrameBase {
  type: 'image';
  image: { asset: AssetPath | null; fit: 'fill' | 'fit' | 'stretch' | 'manual'; focus: [number, number]; crop?: Box };
  placeholderLabel?: string;
}
export interface ShapeFrame extends FrameBase { type: 'shape'; shape: 'rect' | 'rounded' | 'ellipse'; fill: string | null; stroke: { colour: string; width: Pt } | null; text?: TextFrame['content']; style?: StyleId }
export interface GroupFrame extends FrameBase { type: 'group'; children: Frame[] }
export type Frame = TextFrame | ImageFrame | ShapeFrame | GroupFrame;

export interface Run { text: string; style?: StyleId; bold?: boolean; italic?: boolean; link?: string }
export interface Flow { id: FlowId; source: AssetPath; frames: FrameId[]; autoAddPages: boolean }

export interface ParagraphStyle {
  id: StyleId; name: string; basedOn?: StyleId;
  family: string; size: Pt; leading: Pt; weight: number; italic: boolean; tracking: number; // em/1000
  align: 'left' | 'center' | 'right' | 'justify'; firstIndent: Pt; spaceBefore: Pt; spaceAfter: Pt;
  hyphenate: boolean; widows: number; orphans: number; wrap: 'normal' | 'preserve';
  dropCap?: { lines: number; chars: number }; openType?: string[];
  keepWithNext?: boolean; startOn?: 'any' | 'recto' | 'next-page';
  colour: string; // swatch id or #rrggbb
  role?: 'chapter-title' | 'section-title' | 'body' | 'caption' | 'callout' | 'folio' | 'running-head' | 'poem' | 'epigraph';
}

export interface Master { id: MasterId; name: string; frames: Frame[] } // text may use tokens: {page} {book.title} {chapter.title}

export interface BookMetadata {
  isbn: { paperback: string | null; hardcover: string | null; ebook: string | null };
  description: string; keywords: string[]; series: { name: string; number: number } | null;
  publisher?: string; copyrightYear?: number; rights?: string;
}

// ── Export ──
export type ExportTarget = 'kindle' | 'kobo' | 'paperback' | 'hardcover' | 'printpdf' | 'sharepdf';
export type Paper = 'white' | 'cream' | 'colour';
export interface ExportSettings {
  targets: ExportTarget[];
  folder: string;
  print: { paper: Paper; standard: 'PDF/X-4' | 'PDF/X-1a:2001' | 'PDF/X-3'; outputIntent: 'GRACoL2013' | 'FOGRA39' | 'custom'; iccPath?: string; cropMarks: boolean; slug: Pt; imageMinPpi: number };
  ebook: { imageLongEdge: 1600 | 2560 | 'original'; embedFonts: boolean; kepub: boolean; toc: boolean };
  share: { spreads: boolean; bookmarks: boolean; downsamplePpi: 150 | 200 | 'original' };
}
export interface CoverMaths { spine: Pt; edge: Pt; width: Pt; height: Pt; spineTextAllowed: boolean; barcode: Box }

// ── Preflight / Jax ──
export type Severity = 'error' | 'warning' | 'info' | 'success';
export interface Issue { code: string; severity: Severity; message: string; fix?: string; spread?: SpreadId; frame?: FrameId; target?: ExportTarget }
export interface CheckItem { ok: boolean; text: string; code?: string }
export interface JaxAnswer { text: string; source: { title: string; chunkId: string }; confidence: number; actions: { label: string; intent: string }[]; tier: 'A' | 'B' }

// ── Intents (UI → Rust) ──
export type Intent =
  | { type: 'MoveFrame'; spread: SpreadId; frame: FrameId; box: Box }
  | { type: 'SetText'; frame: FrameId; text: string }
  | { type: 'SetStyle'; frame: FrameId; style: StyleId }
  | { type: 'OverrideStyle'; frame: FrameId; overrides: Partial<ParagraphStyle> }
  | { type: 'AddFrame'; spread: SpreadId; frame: Frame }
  | { type: 'DeleteFrame'; spread: SpreadId; frame: FrameId }
  | { type: 'Reorder'; spread: SpreadId; frame: FrameId; to: 'front' | 'back' | number }
  | { type: 'AddSpread'; after: SpreadId; duplicate?: boolean }
  | { type: 'DeleteSpread'; spread: SpreadId }
  | { type: 'MoveSpread'; spread: SpreadId; to: number }
  | { type: 'SetBookGeometry'; trim?: Size; margins?: Margins; bleed?: Pt; grid?: Grid };
